import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec3, mix, texture, uniform } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const { Group, PlaneGeometry, ClampToEdgeWrapping, Color } = THREE;

  // --- Asset dimensions from atlas region ---
  const sourceW = 512;
  const sourceH = 320;
  const aspect = sourceW / sourceH;

  // --- Geometry ---
  const geometry = new PlaneGeometry(aspect, 1);

  // --- Colors from spec palette ---
  const surfaceColor = new Color(0x0b0b10);
  const paperColor = new Color(0xe8ecf2);

  // --- TSL nodes ---
  const uvNode = uv();
  const gradientFactor = uvNode.y; // 0 at top, 1 at bottom
  const gradientColor = mix(vec3(surfaceColor.r, surfaceColor.g, surfaceColor.b),
                              vec3(paperColor.r, paperColor.g, paperColor.b),
                              gradientFactor);

  // --- Texture placeholder, will be replaced after load ---
  const tempTex = new THREE.Texture();
  const textureNode = texture(tempTex);

  // --- Final color: gradient base with subtle grain overlay ---
  const grainStrength = uniform(0.2);
  const grainOverlay = mix(gradientColor, gradientColor.mul(textureNode), grainStrength);
  const colorNode = grainOverlay;

  // --- Material ---
  const material = new MeshBasicNodeMaterial({
    colorNode,
    transparent: false,
  });

  // --- Mesh ---
  const mesh = new THREE.Mesh(geometry, material);
  const group = new Group();
  group.add(mesh);

  // --- Position from config (scene position will be applied externally) ---
  mesh.position.set(0, -0.3, 0);

  // --- Texture loading with atlas UV adjustment ---
  ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
    // Determine full image dimensions (assume power-of-two, but use actual)
    const imgW = tex.image.width;
    const imgH = tex.image.height;

    // Set UV offset/repeat to crop to atlas region (0,0,sourceW,sourceH)
    tex.offset.x = 0;
    tex.offset.y = 0;
    tex.repeat.x = sourceW / imgW;
    tex.repeat.y = sourceH / imgH;
    tex.wrapS = ClampToEdgeWrapping;
    tex.wrapT = ClampToEdgeWrapping;
    tex.needsUpdate = true;

    // Replace the placeholder texture in the node
    material.colorNode = (() => {
      const texNode = texture(tex);
      return mix(gradientColor, gradientColor.mul(texNode), grainStrength);
    })();
    material.needsUpdate = true;
  }).catch((err) => {
    console.error('Failed to load ceramic-grain texture:', err);
  });

  // --- User data handlers (none) ---
  group.userData.handlers = {};

  // --- Cleanup ---
  group.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    tempTex.dispose();
    // No gsap timelines to kill
  };

  return group;
}
